package com.raikar.moviegallery.ui.bridge

import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch

/**
 * Lets Swift observe a ViewModel's [StateFlow], which it can't collect on its own. Written by
 * hand rather than generated by SKIE or KMP-NativeCoroutines, because both are compiler plugins
 * pinned to a Kotlin version (share-viewmodels design, decision 4).
 *
 * A class rather than an extension function because Objective-C export keeps class generics, so
 * Swift sees `StateFlowWatcher<HomeUiState>`.
 *
 * Intended Swift use, one per screen:
 * ```swift
 * final class HomeModel: ObservableObject {
 *     @Published private(set) var state: HomeUiState
 *     private let handle: WatchHandle
 *     init(viewModel: HomeViewModel) {
 *         let watcher = StateFlowWatcher<HomeUiState>(flow: viewModel.uiState)
 *         state = watcher.value
 *         handle = watcher.watch { [weak self] in self?.state = $0 }
 *     }
 *     deinit { handle.cancel() }
 * }
 * ```
 */
class StateFlowWatcher<T : Any>(
    private val flow: StateFlow<T>,
) {
    /** The current value, for a SwiftUI view's initial state. */
    val value: T get() = flow.value

    /**
     * Calls [onEach] with the current value, then with every change, on the main thread (SwiftUI
     * requires it), until the returned handle is cancelled.
     */
    fun watch(onEach: (T) -> Unit): WatchHandle {
        val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main)
        scope.launch { flow.collect { onEach(it) } }
        return WatchHandle(scope)
    }
}

/** Stops one [StateFlowWatcher.watch]. Safe to call more than once. */
class WatchHandle internal constructor(
    private val scope: CoroutineScope,
) {
    val isActive: Boolean get() = scope.coroutineContext[Job]?.isActive == true

    fun cancel() = scope.cancel()
}
